-- Additive migration. Historical orders have no tb_order_detail row and remain read-only.
CREATE TABLE IF NOT EXISTS tb_business_meta (id int PRIMARY KEY, version int NOT NULL);
CREATE TABLE IF NOT EXISTS tb_admin (user_id bigint unsigned PRIMARY KEY, create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS tb_shop_member (shop_id bigint unsigned NOT NULL,user_id bigint unsigned NOT NULL,role varchar(16) NOT NULL DEFAULT 'OWNER',PRIMARY KEY(shop_id,user_id),KEY idx_member_user(user_id));
CREATE TABLE IF NOT EXISTS tb_shop_settings (shop_id bigint unsigned PRIMARY KEY,status tinyint NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS tb_voucher_policy (voucher_id bigint unsigned PRIMARY KEY,valid_days int DEFAULT NULL,valid_until timestamp NULL DEFAULT NULL,min_spend bigint unsigned NOT NULL DEFAULT 0,refund_allowed tinyint NOT NULL DEFAULT 1,ready tinyint NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS tb_order_detail (order_id bigint PRIMARY KEY,shop_id bigint unsigned NOT NULL,voucher_type tinyint NOT NULL,title varchar(255) NOT NULL,rules varchar(1024) NOT NULL,pay_value bigint unsigned NOT NULL,actual_value bigint NOT NULL,valid_days int DEFAULT NULL,valid_until timestamp NULL DEFAULT NULL,min_spend bigint unsigned NOT NULL DEFAULT 0,refund_allowed tinyint NOT NULL DEFAULT 1,expires_at timestamp NOT NULL,close_reason varchar(32) DEFAULT NULL,KEY idx_detail_expiry(expires_at,order_id));
CREATE TABLE IF NOT EXISTS tb_stock_ledger (order_id bigint NOT NULL,kind varchar(16) NOT NULL,voucher_id bigint unsigned NOT NULL,quantity int NOT NULL DEFAULT 1,reason varchar(32) DEFAULT NULL,create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(order_id,kind),KEY idx_ledger_voucher(voucher_id,kind));
CREATE TABLE IF NOT EXISTS tb_payment (id varchar(36) PRIMARY KEY,order_id bigint NOT NULL,user_id bigint unsigned NOT NULL,request_id varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,channel varchar(16) NOT NULL DEFAULT 'MOCK',amount bigint unsigned NOT NULL,status varchar(16) NOT NULL DEFAULT 'PENDING',create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,pay_time timestamp NULL DEFAULT NULL,UNIQUE KEY uk_payment_order(order_id),UNIQUE KEY uk_payment_request(user_id,request_id));
CREATE TABLE IF NOT EXISTS tb_payment_notice (id varchar(64) CHARACTER SET ascii COLLATE ascii_bin PRIMARY KEY,payment_id varchar(36) NOT NULL,result varchar(16) NOT NULL,amount bigint unsigned NOT NULL,state tinyint NOT NULL DEFAULT 0,attempts int NOT NULL DEFAULT 0,last_error varchar(64) DEFAULT NULL,create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_notice_pending(state,create_time));
CREATE TABLE IF NOT EXISTS tb_user_voucher (id varchar(36) PRIMARY KEY,order_id bigint NOT NULL,user_id bigint unsigned NOT NULL,shop_id bigint unsigned NOT NULL,code varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,status varchar(16) NOT NULL DEFAULT 'UNUSED',valid_until timestamp NULL DEFAULT NULL,create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,use_time timestamp NULL DEFAULT NULL,UNIQUE KEY uk_user_voucher_order(order_id),UNIQUE KEY uk_user_voucher_code(code),KEY idx_user_voucher_owner(user_id,status));
CREATE TABLE IF NOT EXISTS tb_refund (id varchar(36) PRIMARY KEY,payment_id varchar(36) NOT NULL,order_id bigint NOT NULL,user_id bigint unsigned NOT NULL,request_id varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,amount bigint unsigned NOT NULL,reason varchar(32) NOT NULL,status varchar(16) NOT NULL DEFAULT 'PENDING',attempts int NOT NULL DEFAULT 0,last_error varchar(64) DEFAULT NULL,create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,refund_time timestamp NULL DEFAULT NULL,UNIQUE KEY uk_refund_payment(payment_id),UNIQUE KEY uk_refund_request(user_id,request_id));
CREATE TABLE IF NOT EXISTS tb_redemption (id varchar(36) PRIMARY KEY,user_voucher_id varchar(36) NOT NULL,order_id bigint NOT NULL,shop_id bigint unsigned NOT NULL,operator_id bigint unsigned NOT NULL,consumption_amount bigint unsigned NOT NULL,request_id varchar(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uk_redemption_voucher(user_voucher_id),UNIQUE KEY uk_redemption_request(operator_id,request_id));
CREATE TABLE IF NOT EXISTS tb_favorite (user_id bigint unsigned NOT NULL,shop_id bigint unsigned NOT NULL,create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,shop_id));
CREATE TABLE IF NOT EXISTS tb_blog_like (blog_id bigint unsigned NOT NULL,user_id bigint unsigned NOT NULL,create_time timestamp(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),PRIMARY KEY(blog_id,user_id));
CREATE TABLE IF NOT EXISTS tb_blog_visibility (blog_id bigint unsigned PRIMARY KEY,status tinyint NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS tb_social_follow (user_id bigint unsigned NOT NULL,follow_user_id bigint unsigned NOT NULL,create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,follow_user_id),KEY idx_social_follow_target(follow_user_id));
-- Existing follow records are preserved and deduplicated in the new authoritative relationship table.
INSERT IGNORE INTO tb_social_follow(user_id,follow_user_id,create_time) SELECT user_id,follow_user_id,MIN(create_time) FROM tb_follow WHERE user_id<>follow_user_id GROUP BY user_id,follow_user_id;
CREATE TABLE IF NOT EXISTS tb_upload (id varchar(36) PRIMARY KEY,user_id bigint unsigned NOT NULL,path varchar(255) NOT NULL,create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE KEY uk_upload_path(path));
CREATE TABLE IF NOT EXISTS tb_shop_review (order_id bigint PRIMARY KEY,shop_id bigint unsigned NOT NULL,user_id bigint unsigned NOT NULL,score int NOT NULL,content varchar(1000) NOT NULL,create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_review_shop(shop_id,create_time));
CREATE TABLE IF NOT EXISTS tb_operation_audit(id varchar(36) PRIMARY KEY,operator_id bigint unsigned NOT NULL,action varchar(48) NOT NULL,resource_id varchar(64) NOT NULL,create_time timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,KEY idx_audit_operator(operator_id,create_time));
INSERT INTO tb_business_meta(id,version) VALUES(1,6) ON DUPLICATE KEY UPDATE version=GREATEST(version,6);
